// Components/CartSummaryViewComponent.cs
public class CartSummaryViewComponent : ViewComponent
{
    private readonly IShoppingCart _cart;

    public CartSummaryViewComponent(IShoppingCart cart)
    {
        _cart = cart;
    }

    public async Task<IViewComponentResult> InvokeAsync()
    {
        var items = await _cart.GetItemsAsync(HttpContext.User);
        return View(items);
    }
}

<!-- Views/Shared/Components/CartSummary/Default.cshtml -->
@model IEnumerable<CartItem>
<span class="badge">@Model.Count() items</span>

<!-- Usage in any view -->
@await Component.InvokeAsync("CartSummary")

// Components/PopularProductsViewComponent.cs
public class PopularProductsViewComponent : ViewComponent
{
    private readonly IProductRepository _repo;

    public PopularProductsViewComponent(IProductRepository repo)
    {
        _repo = repo;
    }

    public async Task<IViewComponentResult> InvokeAsync(int count = 5)
    {
        var products = await _repo.GetPopularAsync(count);
        return View(products);
    }
}

<!-- Usage -->
@await Component.InvokeAsync("PopularProducts", new { count = 10 })

<!-- Or with tag helper -->
<vc:popular-products count="10" />
